// --- keyboard reorder ---------------------------------------------------
await page.locator('.orders-table__table').first().locator('[data-column-id="city"]').focus();
await page.keyboard.press('Alt+ArrowLeft');
await page.keyboard.press('Alt+ArrowLeft');
log('after Alt+Left x2:', (await headerTitles()).join(' | '));
log('focus still on city header:', await page.evaluate(() => document.activeElement?.getAttribute('data-column-id')));
