await page.getByRole('button', { name: 'Развернуть все' }).click();
await page.getByText('Группировать по статусу').click();
log('ungrouped: tables', await page.locator('.orders-table__table').count(), '| rows', await page.locator('tbody tr').count());
await page.screenshot({ path: `${out}/05-flat.png` });
await page.getByText('Группировать по статусу').click();

// --- sidebar ------------------------------------------------------------
await page.getByRole('button', { name: 'Свернуть меню' }).click();
await page.waitForTimeout(300);
log('sidebar collapsed width:', (await page.locator('.sidebar').boundingBox()).width);
await page.locator('.sidebar__item').nth(1).hover();
