  gap: 12px 24px;
}

.orders-table__heading {
  display: flex;
  align-items: baseline;
  gap: 12px;
}

.orders-table__title {
  margin: 0;
}

.orders-table__controls {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px 16px;
}

.orders-table__hint {
  margin: 8px 0 16px;
}

.orders-table__body {
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-width: 0;
}

.orders-table__table {
  background: var(--g-color-base-float);
  border: 1px solid var(--g-color-line-generic);
  border-radius: 8px;
}

.orders-table__table .g-table__cell {
  box-sizing: border-box;
}

.orders-table__table .g-table__head .g-table__cell {
  position: relative;
  padding: 0;
  background: var(--g-color-base-generic-ultralight);
  color: var(--g-color-text-secondary);
  white-space: nowrap;
  user-select: none;
}

.orders-table__table .g-table__head .g-table__cell:first-child {
  border-start-start-radius: 8px;
}

.orders-table__table .g-table__head .g-table__cell:last-child {
  border-start-end-radius: 8px;
}

.orders-table__table .g-table__head .g-table__checkbox_cell {
  padding: 11px var(--g-spacing-2) 10px;
}

.orders-table__table .g-table__body .g-table__row:last-child .g-table__cell {
  border-block-end: none;
}

.orders-table__mono {
  font-variant-numeric: tabular-nums;
}

/* ---- draggable column header -------------------------------------------- */

.column-header {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 11px var(--g-spacing-2) 10px;
  cursor: grab;
  border-radius: 4px;
}

.column-header:hover {
  background: var(--g-color-base-simple-hover);
  color: var(--g-color-text-primary);
}

.column-header:focus-visible {
  outline: 2px solid var(--g-color-line-focus);
  outline-offset: -2px;
}

.column-header_align_end {
  flex-direction: row-reverse;
}

.column-header__grip {
  flex-shrink: 0;
  color: var(--g-color-text-hint);
}

.column-header:hover .column-header__grip,
.column-header:focus-visible .column-header__grip {
  color: var(--g-color-text-secondary);
}

.column-header_dragging {
  opacity: 0.4;
  cursor: grabbing;
}

.orders-table__body_dragging .column-header {
  cursor: grabbing;
}

.column-header::after {
  content: '';
  position: absolute;
  top: 4px;
  bottom: 4px;
  width: 3px;
  border-radius: 2px;
  background: var(--g-color-line-brand);
  opacity: 0;
  pointer-events: none;
}

.column-header_over_before::after {
  inset-inline-start: -1px;
  opacity: 1;
}

.column-header_over_after::after {
  inset-inline-end: -1px;
  opacity: 1;
}

/* ---- status groups -------------------------------------------------------- */

.orders-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.orders-group__header {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  margin: 0;
  padding: 6px 8px;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: var(--g-color-text-primary);
  font: inherit;
  text-align: start;
  cursor: pointer;
}

.orders-group__header:hover {
  background: var(--g-color-base-simple-hover);
}

.orders-group__header:focus-visible {
  outline: 2px solid var(--g-color-line-focus);
  outline-offset: 1px;
}

.orders-group__count {
  margin-inline-start: 2px;
}

.orders-group__selected {
  margin-inline-start: auto;
}

/* ---- bulk actions --------------------------------------------------------- */

.orders-table__actions {
  position: sticky;
  bottom: 16px;
  display: flex;
  justify-content: center;
  margin-top: 24px;
  pointer-events: none;
}

.orders-table__actions > * {
  pointer-events: auto;
}
